U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
cut=pd.Timestamp('2026-10-08'); series={}
for s in U:
 d=get_stock_daily_data(s,3000)
 if d is not None:
  d=d.sort_values('date').set_index('date'); series[s]=d.close.astype(float).pct_change()
R=pd.DataFrame(series).sort_index(); bench=R['SPX']
# residual momentum: trailing 40d cumulative residual after rolling beta to SPX, predicts next returns
beta=R.rolling(60,min_periods=40).cov(bench).div(bench.rolling(60,min_periods=40).var(),axis=0)
res=R-beta.mul(bench,axis=0)
f=res.rolling(40,min_periods=30).sum()
fr={h:R.shift(-1).rolling(h).sum().shift(-(h-1)) for h in [1,3,5,10]}
for h,Y in fr.items():
 z=[]; dates=[]
 for dt in R.index:
  q=pd.DataFrame({'f':f.loc[dt],'y':Y.loc[dt]}).dropna()
  if len(q)>=8:
   z.append(q.f.corr(q.y)); dates.append(dt)
 a=pd.Series(z,index=dates).dropna(); print('H',h,'dates',len(a),'avgN',R.loc[a.index].notna().sum(axis=1).mean(),'IC',a.mean(),'ICIR',a.mean()/a.std(ddof=1),'hit',(a>0).mean())
# coverage, rank turnover
p=f.rank(axis=1,pct=True); print('coverage',f.notna().sum().sum()/(f.shape[0]*f.shape[1]),'turnover',p.diff().abs().mean().mean())
# yearly
for yr,g in a.groupby(a.index.year): print('year',yr,'IC',g.mean(),'n',len(g))
print('corr with raw 20d momentum',f.stack().corr(R.rolling(20).sum().stack()))
"}

